#!/usr/bin/env python3
# Generated by scripts/build-skill.mjs from scripts/ollama/ollama_cast.py in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
"""Make a drawcast with a local model in Ollama (Qwen3 8B, Qwen2.5-coder, …).

    python3 ollama_cast.py "Why does compound interest snowball?"
    python3 ollama_cast.py "How vaccines protect the unvaccinated" --model qwen2.5-coder:7b
    python3 ollama_cast.py "…" --fixer qwen2.5-coder:7b --open

Steps, each a short call so a small model keeps up:
  1. template  — pick a ready template (or none) from a shortlist found by keywords;
  2. plan      — the story as 8–14 spoken lines, each with what it shows;
  3. write     — the cast as one JSON object (Ollama's JSON mode keeps it parseable);
  4. check     — drawcast's own checkers (check_cast.mjs if Node is here, check_cast.py
                 always); the problems go back to the model until it passes (--tries);
  5. save      — <slug>.yaml, and a drawcast.app/#cast= link that plays it at once.

Needs the drawcast skill folder: in the skill zip this script is already inside it
(drawcast/ollama/); else --skill DIR (the unzipped zip, or dist-skill/drawcast after
`npm run build:skill`), or DRAWCAST_SKILL. Python 3.9+, standard library; PyYAML for .yaml output (else .json).
Ollama at OLLAMA_HOST (default http://localhost:11434).
"""
import argparse
import importlib.util
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))


# ---- the skill folder -------------------------------------------------------------------

def find_skill(given):
    candidates = [given, os.environ.get("DRAWCAST_SKILL"),
                  os.path.join(HERE, ".."),  # drawcast/ollama/ in the skill zip
                  os.path.join(HERE, "drawcast"), os.path.join(HERE, "..", "drawcast"),
                  os.path.join(HERE, "..", "..", "dist-skill", "drawcast")]
    for c in candidates:
        if c and os.path.isfile(os.path.join(c, "references", "schema.json")):
            return os.path.abspath(c)
    sys.exit("Cannot find the drawcast skill folder (references/schema.json). Unzip drawcast-skill.zip "
             "and pass --skill <folder>, or set DRAWCAST_SKILL.")


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def load_module(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


# ---- templates --------------------------------------------------------------------------

def template_index(skill):
    """[(id, description, viewer_can)] from references/templates/index.md."""
    out, cur = [], None
    for line in read(os.path.join(skill, "references", "templates", "index.md")).splitlines():
        m = re.match(r"^- \*\*([a-z0-9_]+)\*\*: (.*)$", line)
        if m:
            cur = [m.group(1), m.group(2), ""]
            out.append(cur)
        elif cur and line.strip().startswith("Viewer can:"):
            cur[2] = line.strip()
    return [tuple(t) for t in out]


STOP = set("a an the of and or to in on for with by is are be as at it its this that how why what when does do "
           "from into than then any about show explain me you your can".split())


def words(text):
    return {w for w in re.findall(r"[a-z]{3,}", text.lower()) if w not in STOP}


def shortlist(request, index, n):
    """Templates whose name or description share words with the request, best first."""
    want = words(request)
    scored = []
    for tid, desc, _ in index:
        name_words = set(tid.split("_"))
        score = 3 * len(want & name_words) + len(want & words(desc))
        if score:
            scored.append((score, tid))
    scored.sort(key=lambda s: -s[0])
    return [tid for _, tid in scored[:n]]


def template_brief(skill, tid, max_example=900):
    """A template's first lines, its element ids and short examples — not its long schema."""
    text = read(os.path.join(skill, "references", "templates", tid + ".md"))
    lines = text.splitlines()
    desc = next((l for l in lines[3:8] if l.strip() and not l.startswith("#")), "")
    desc = " ".join(re.split(r"(?<=[.!?])\s+", desc)[:3])
    ids = re.search(r"Element ids your commands can reference:\n(.*?)\nExamples:", text, re.S)
    examples = re.findall(r"^Request: .*$", text, re.M)
    examples = [e for e in examples if len(e) <= max_example][:3]
    parts = ["Template `%s`: %s" % (tid, desc)]
    if ids:
        parts.append("Its element ids (commands name these):\n" + ids.group(1).strip())
    if examples:
        parts.append("Example params:\n" + "\n".join(examples))
    return "\n\n".join(parts)


# ---- Ollama -----------------------------------------------------------------------------

class Ollama:
    def __init__(self, host, ctx, think, verbose):
        self.host = host.rstrip("/")
        self.ctx = ctx
        self.think = think          # None: leave it to the model; True/False: ask for it
        self.verbose = verbose

    def chat(self, model, messages, fmt=None, temperature=0.5):
        body = {"model": model, "messages": messages, "stream": False,
                "options": {"num_ctx": self.ctx, "temperature": temperature}}
        if fmt is not None:
            body["format"] = fmt
        think = self.think
        if think is None and model.lower().startswith("qwen3"):
            think = False           # Qwen3 thinks by default: slow, and the JSON comes out the same
        if think is not None:
            body["think"] = think
        t0 = time.time()
        try:
            data = self.post(body)
        except urllib.error.HTTPError as e:
            msg = e.read().decode("utf-8", "replace")
            if "think" in body and "think" in msg.lower():
                body.pop("think")   # a model that does not do thinking
                data = self.post(body)
            else:
                sys.exit("Ollama said %s: %s" % (e.code, msg))
        content = data.get("message", {}).get("content", "")
        content = re.sub(r"<think>.*?</think>", "", content, flags=re.S).strip()
        n_in, n_out = data.get("prompt_eval_count", 0), data.get("eval_count", 0)
        if n_in >= self.ctx - 50:
            print("  ! the prompt filled the context window (%d tokens): raise --ctx" % n_in, file=sys.stderr)
        if self.verbose:
            print("  (%s: %d tokens in, %d out, %.0f s)" % (model, n_in, n_out, time.time() - t0), file=sys.stderr)
        return content

    def post(self, body):
        req = urllib.request.Request(self.host + "/api/chat", data=json.dumps(body).encode("utf-8"),
                                     headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=900) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.URLError as e:
            if isinstance(e, urllib.error.HTTPError):
                raise
            sys.exit("Cannot reach Ollama at %s (%s). Is `ollama serve` running?" % (self.host, e.reason))


def parse_json(text):
    try:
        return json.loads(text)
    except ValueError:
        pass
    m = re.search(r"\{.*\}", text, re.S)
    if m:
        try:
            return json.loads(m.group(0))
        except ValueError:
            pass
    return None


# ---- the steps --------------------------------------------------------------------------

def short_desc(desc, limit=160):
    first = re.split(r"(?<=[.!?])\s+", desc)[0]
    return first if len(first) <= limit else first[:limit].rsplit(" ", 1)[0] + "…"


def pick_template(ai, model, request, index, n):
    """The model chooses from every template (one short line each), keyword matches first;
    n > 0 offers only the n best keyword matches instead."""
    hits = shortlist(request, index, n if n > 0 else len(index))
    names = hits if n > 0 else hits + [t[0] for t in index if t[0] not in hits]
    if not names:
        return None
    by_id = {t[0]: t for t in index}
    menu = "\n".join("- %s: %s" % (t, short_desc(by_id[t][1])) for t in names)
    fmt = {"type": "object", "properties": {"template": {"type": "string", "enum": names + ["none"]}},
           "required": ["template"]}
    answer = ai.chat(model, [
        {"role": "system", "content": "You choose a ready-made figure template for a short teaching video. "
                                      "Answer in JSON."},
        {"role": "user", "content": "The video: %s\n\nTemplates:\n%s\n\nPick the ONE template whose figure "
                                    "tells THIS story directly. If none clearly fits, answer \"none\" (the "
                                    "figure is then drawn freehand) — a template that only shares a word with "
                                    "the topic is wrong." % (request, menu)}], fmt=fmt, temperature=0.1)
    choice = (parse_json(answer) or {}).get("template")
    return choice if choice in names else None


def make_plan(ai, model, request, brief, lines):
    fmt = {"type": "object", "properties": {
        "title": {"type": "string"},
        "insight": {"type": "string"},
        "beats": {"type": "array", "items": {"type": "object", "properties": {
            "say": {"type": "string"}, "show": {"type": "string"}}, "required": ["say", "show"]}}},
        "required": ["title", "insight", "beats"]}
    prompt = (
        "Plan a short narrated teaching figure (a drawcast) for: %s\n\n"
        "Write the story first, as %s beats. Each beat: `say`, one or two short spoken sentences, and `show`, "
        "what appears or changes on the figure at that moment (a few words). The first beat asks the question; "
        "then one concrete example with correct numbers, one change at a time; the last beat names the one "
        "insight in fresh plain words. Connect the sentences like a good teacher talking, not a list. "
        "Never invent studies or statistics: illustrative numbers, said to be so.%s\n\n"
        "Give `title` (a few words), `insight` (one sentence) and `beats`."
        % (request, lines, ("\n\nThe figure will be drawn with this template, so plan around what it can show:\n"
                            + brief) if brief else ""))
    return parse_json(ai.chat(model, [{"role": "user", "content": prompt}], fmt=fmt, temperature=0.6))


def system_prompt(skill, full):
    parts = [re.sub(r"^<!--.*?-->\n", "", read(os.path.join(HERE, "rules-small.md")), flags=re.S)]
    # The skill's skeleton in the repo; on a machine with only the skill folder, one of its examples.
    for example_path in (os.path.join(HERE, "skeleton.yaml"),  # beside it in the skill zip
                         os.path.join(HERE, "..", "skill", "skeleton.yaml"),
                         os.path.join(skill, "references", "examples", "parabola-coefficients.yaml")):
        if os.path.isfile(example_path):
            example = "\n".join(l for l in read(example_path).splitlines() if not l.startswith("#")) + "\n"
            break
    else:
        example = None
    if example:
        parts.append("## A valid drawcast (shown as YAML; you write the same as JSON)\n\n```yaml\n%s```" % example)
    if full:
        refs = os.path.join(skill, "references")
        parts.append("# More rules\n\n" + read(os.path.join(refs, "storyline.md")))
        parts.append(read(os.path.join(refs, "rule-card.md")))
    parts.append("Answer with the JSON object only.")
    return "\n\n".join(parts)


def write_request(request, plan, tid, brief):
    out = ["Make the drawcast for: " + request]
    if plan:
        out.append("Follow this plan (one command with `speak` per beat, after the `card`; use the `say` "
                   "text, improved if needed):\n" + json.dumps(plan, ensure_ascii=False, indent=1))
    if tid:
        out.append("Use the template. Write `\"template\": \"%s\"` and its `params`; draw and highlight its "
                   "element ids. You may add a few elements of your own if the plan needs them.\n\n%s"
                   % (tid, brief))
    else:
        out.append("No template: build the figure from elements.")
    return "\n\n".join(out)


# ---- checking ---------------------------------------------------------------------------

class Checker:
    def __init__(self, skill):
        self.skill = skill
        self.py = load_module(os.path.join(skill, "scripts", "check_cast.py"), "check_cast")
        with open(os.path.join(skill, "references", "schema.json"), encoding="utf-8") as f:
            self.schema = json.load(f)
        mjs = os.path.join(skill, "scripts", "check_cast.mjs")
        self.node = shutil.which("node") if os.path.isfile(mjs) else None
        self.mjs = mjs

    def problems(self, spec):
        """(errors, warnings): errors make the player skip or refuse; warnings are likely mistakes."""
        text = json.dumps(spec, ensure_ascii=False)
        errors, warnings = [], []
        ok, _, found = self.py.check(text, self.schema)
        for p in found:
            (warnings if p.startswith("warning: ") else errors).append(p.replace("warning: ", ""))
        if self.node:
            with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8") as f:
                f.write(text)
            try:
                r = subprocess.run([self.node, self.mjs, f.name], capture_output=True, text=True, timeout=120)
                if r.returncode != 0:
                    node_errors = [l[2:] for l in r.stdout.splitlines() if l.startswith("- ")]
                    errors = node_errors or errors or [r.stdout.strip() or r.stderr.strip()]
            finally:
                os.unlink(f.name)
        errors += own_checks(spec)
        return errors, warnings


def own_checks(spec):
    """What small models get wrong that the checkers let through."""
    out = []
    cmds = spec.get("commands") if isinstance(spec.get("commands"), list) else []
    if not cmds:
        out.append("there are no commands")
        return out
    if not (isinstance(cmds[0], dict) and "card" in cmds[0]):
        out.append('the first command must be a card: {"card": {"title": "..."}}')
    bare = 0
    for i, c in enumerate(cmds):
        if isinstance(c, dict) and set(c) <= {"speak", "cue", "blocking"} and "speak" in c:
            bare += 1
            if bare == 2:
                out.append("commands #%d and #%d only speak: put each speak on the command that draws or "
                           "highlights what it says" % (i, i + 1))
        else:
            bare = 0
    spoken = sum(1 for c in cmds if isinstance(c, dict) and isinstance(c.get("speak"), str) and c["speak"].strip())
    if spoken < 4:
        out.append("only %d spoken lines: tell the whole story, 8 to 14 lines" % spoken)
    return out


def tidy(spec):
    """Small, safe repairs before checking."""
    if not isinstance(spec, dict):
        return spec
    if isinstance(spec.get("params"), dict):
        spec["params"].pop("title", None)
    if not spec.get("template"):
        spec.pop("params", None)
    for key in ("elements", "commands"):
        if key in spec and isinstance(spec[key], dict):
            spec[key] = [spec[key]]
    for c in spec.get("commands") or []:
        if isinstance(c, dict):
            for verb in ("draw", "erase"):
                if isinstance(c.get(verb), str):
                    c[verb] = [c[verb]]
    return spec


# ---- saving -----------------------------------------------------------------------------

def to_text(spec):
    """YAML in the order the app writes it, or JSON without PyYAML."""
    order = ["title", "template", "domain", "vars", "params", "elements", "commands"]
    spec = {k: spec[k] for k in order if k in spec} | {k: v for k, v in spec.items() if k not in order}
    try:
        import yaml
    except ImportError:
        return json.dumps(spec, ensure_ascii=False, indent=1), ".json"
    return yaml.safe_dump(spec, sort_keys=False, allow_unicode=True, width=110, default_flow_style=None), ".yaml"


def slug(title):
    s = re.sub(r"[^a-z0-9]+", "-", (title or "drawcast").lower()).strip("-")
    return s[:50] or "drawcast"


# ---- main -------------------------------------------------------------------------------

def main():
    ap = argparse.ArgumentParser(description="Make a drawcast with a local Ollama model.")
    ap.add_argument("request", help="what the drawcast should explain")
    ap.add_argument("--model", default=os.environ.get("DRAWCAST_MODEL", "qwen3:8b"))
    ap.add_argument("--fixer", help="model for the repair rounds (default: --model)")
    ap.add_argument("--host", default=os.environ.get("OLLAMA_HOST", "http://localhost:11434"))
    ap.add_argument("--ctx", type=int, default=16384, help="context window in tokens (default 16384)")
    ap.add_argument("--tries", type=int, default=4, help="repair rounds after the first draft (default 4)")
    ap.add_argument("--template", help="use this template (or 'none'), skipping the choice")
    ap.add_argument("--shortlist", type=int, default=0, help="offer only the N best keyword matches (default: all "
                    "templates, ~4k tokens)")
    ap.add_argument("--lines", default="8 to 12", help='spoken lines in the plan (default "8 to 12")')
    ap.add_argument("--no-plan", action="store_true", help="write the cast in one go, without a story plan")
    ap.add_argument("--full", action="store_true", help="add the full storyline + rule card (~10k tokens more; "
                                                       "use --ctx 32768)")
    ap.add_argument("--think", choices=["on", "off"], help="Qwen3 thinking (default off)")
    ap.add_argument("--skill", help="the drawcast skill folder")
    ap.add_argument("--out", default=".", help="folder for the cast (default: here)")
    ap.add_argument("--open", action="store_true", help="open the link in the browser")
    ap.add_argument("-q", "--quiet", action="store_true")
    a = ap.parse_args()

    skill = find_skill(a.skill)
    think = None if a.think is None else a.think == "on"
    ai = Ollama(a.host, a.ctx, think, not a.quiet)
    fixer = a.fixer or a.model
    log = (lambda *m: None) if a.quiet else (lambda *m: print(*m, file=sys.stderr))
    checker = Checker(skill)
    index = template_index(skill)

    # 1. template
    tid = None
    if a.template and a.template != "none":
        if a.template not in {t[0] for t in index}:
            sys.exit("No template %r. Templates: %s" % (a.template, ", ".join(t[0] for t in index)))
        tid = a.template
    elif not a.template:
        log("1. choosing a template …")
        tid = pick_template(ai, a.model, a.request, index, a.shortlist)
    brief = template_brief(skill, tid) if tid else ""
    log("   template: %s" % (tid or "none (freehand)"))

    # 2. plan
    plan = None
    if not a.no_plan:
        log("2. planning the story …")
        plan = make_plan(ai, a.model, a.request, brief, a.lines)
        if plan and not a.quiet:
            for b in plan.get("beats", []):
                log("   · %s  [%s]" % (b.get("say", ""), b.get("show", "")))

    # 3. write
    log("3. writing the cast …")
    system = system_prompt(skill, a.full)
    asked = write_request(a.request, plan, tid, brief)
    messages = [{"role": "system", "content": system}, {"role": "user", "content": asked}]
    raw = ai.chat(a.model, messages, fmt="json", temperature=0.4)
    spec = tidy(parse_json(raw))

    # 4. check and repair
    errors, warnings = (["the answer was not a JSON object"], []) if not isinstance(spec, dict) \
        else checker.problems(spec)
    for n in range(a.tries):
        must = errors + ["warning: " + w for w in warnings if "no element" in w]
        if not must:
            break
        log("4. round %d: %d problem(s) to fix" % (n + 1, len(must)))
        for p in must[:8]:
            log("   - " + p)
        fix = [{"role": "system", "content": system},
               {"role": "user", "content": asked},
               {"role": "assistant", "content": json.dumps(spec, ensure_ascii=False) if isinstance(spec, dict) else raw},
               {"role": "user", "content": "drawcast's checker found these problems:\n" + "\n".join(
                   "- " + p for p in must[:15]) + "\n\nFix every one and answer with the WHOLE corrected JSON "
                   "object. Change only what is needed."}]
        raw = ai.chat(fixer, fix, fmt="json", temperature=0.2)
        new = tidy(parse_json(raw))
        if isinstance(new, dict):
            spec = new
            errors, warnings = checker.problems(spec)

    if not isinstance(spec, dict):
        sys.exit("The model did not write a JSON object. Try again, or another --model.")

    # 5. save
    text, ext = to_text(spec)
    os.makedirs(a.out, exist_ok=True)
    path = os.path.join(a.out, slug(spec.get("title")) + ext)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    link_mod = load_module(os.path.join(skill, "scripts", "make_link.py"), "make_link")
    link = link_mod.make_link(text.encode("utf-8"))
    spoken = sum(1 for c in spec.get("commands") or [] if isinstance(c, dict) and c.get("speak"))

    if errors:
        print("NOT VALID after %d repair round(s) — saved anyway, the player will list what it skips:" % a.tries)
        for p in errors:
            print("- " + p)
    else:
        print("OK — %d spoken lines%s" % (spoken, ", template " + tid if tid else ""))
    for w in warnings:
        print("  warning: " + w)
    print(path)
    print(link)
    if a.open:
        import webbrowser
        webbrowser.open(link)
    return 0 if not errors else 1


if __name__ == "__main__":
    sys.exit(main())
